@Override
    public void tick() {
        super.tick();
        if (tickCount == 1) {
            // prevent first-tick flicker due to deltaMoveOld being "uninitialized" on our first tick
            deltaMovementOld = getDeltaMovement();
        }
        if (tickCount > EXPIRE_TIME) {
            discard();
            return;
        }
        if (level.isClientSide) {
            trailParticles();
        }
        handleEntityHoming();
        handleCursorHoming();
        handleHitDetection();
        travel();
        deltaMovementOld = getDeltaMovement();
        rotateWithMotion();
    }

public void handleHitDetection() {
        Vec3 position = position();
        Vec3 destination = position.add(getDeltaMovement());
        HitResult blockCollision = level.clip(new ClipContext(position, destination, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
        if (collidesWithBlocks() && blockCollision.getType() != HitResult.Type.MISS) {
            destination = blockCollision.getLocation();
        }
        List<HitResult> entities = raycastForEntitiesAlongPath(destination, position);
        for (HitResult hitResult : entities) {
            if (!(hitResult instanceof EntityHitResult entityHitResult)) {
                continue;
            }
            if (entityHitResult.getType() != HitResult.Type.MISS && !NeoForge.EVENT_BUS.post(new ProjectileImpactEvent(this, entityHitResult)).isCanceled()) {
                onHit(entityHitResult);
            }
            if (this.isRemoved()) {
                break;
            }
        }
        if (blockCollision.getType() != HitResult.Type.MISS) {
            onHit(blockCollision);
        }
    }

@Override
    protected void onHit(@NotNull HitResult hitresult) {
        super.onHit(hitresult);
        if (!level.isClientSide && hitresult.getType() != HitResult.Type.MISS) {
            if (hitresult.getType() != HitResult.Type.BLOCK || collidesWithBlocks()) {
                var vec = hitresult.getLocation();
                impactParticles(vec.x, vec.y, vec.z);
                getImpactSound().ifPresent(this::doImpactSound);
            }
        }
    }

@Override
    protected void onHitEntity(@NotNull EntityHitResult pResult) {
        super.onHitEntity(pResult);
        if (!shouldPierceShields() && (pResult.getEntity() instanceof ShieldPart || pResult.getEntity() instanceof AbstractShieldEntity)) {
            // simulate block impact (likely destroying projectile) due to magic shield impact
            this.onHitBlock(new BlockHitResult(pResult.getEntity().position(), Direction.fromYRot(this.getYRot()), pResult.getEntity().blockPosition(), false));
        }
    }

@Override
    public boolean applyEffectTick(LivingEntity entity, int pAmplifier) {
        var radiusSqr = 400; //20
        entity.level.getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(20, 12, 20),
                        livingEntity -> livingEntity != entity &&
                                horizontalDistanceSqr(livingEntity, entity) < radiusSqr &&
                                livingEntity.isPickable() &&
                                !livingEntity.isSpectator() &&
                                !Utils.shouldHealEntity(entity, livingEntity) &&
                                Utils.hasLineOfSight(entity.level, entity, livingEntity, false)
                )
                .forEach(targetEntity -> {
                    LightningStrike lightningStrike = new LightningStrike(entity.level);
                    lightningStrike.setOwner(entity);
                    lightningStrike.setDamage(getDamageFromAmplifier(pAmplifier, entity));
                    lightningStrike.setPos(targetEntity.position());
                    entity.level.addFreshEntity(lightningStrike);
                });
        return true;
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        entity.addEffect(new MobEffectInstance(MobEffectRegistry.THUNDERSTORM, getDurationTicks(spellLevel, entity), getAmplifierForLevel(spellLevel, entity), false, false, true));
        int count = 3;
        for (int i = 0; i < count; i++) {
            Vec3 offset = new Vec3(0, 5 + level.getRandom().nextFloat() * 2, 2 + level.getRandom().nextFloat());
            offset = offset.yRot(i * Mth.TWO_PI / count);
            Vec3 location = entity.position().add(offset);
            MagicManager.spawnParticles(level, ParticleHelper.FOG_THUNDER_LIGHT, location.x, location.y, location.z, 2, 1, 1, 1, 1, true);
            MagicManager.spawnParticles(level, ParticleHelper.FOG_THUNDER_DARK, location.x, location.y, location.z, 2, 1, 1, 1, 1, true);
            MagicManager.spawnParticles(level, new ZapParticleOption(location), entity.getX(), entity.getY(), entity.getZ(), 1, 1,0,1,0, true);
        }
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

@Override
