        return pDuration % 40 == 0;
    }

public static float getDamageFromAmplifier(int effectAmplifier, @Nullable LivingEntity caster) {
        var power = caster == null ? 1 : SpellRegistry.THUNDERSTORM_SPELL.get().getEntityPowerMultiplier(caster);
        return (((effectAmplifier - 7) * power) + 7);
    }

@Override
    public void tick() {
        if (level.isClientSide) {
            return;
        }
        if (tickCount == 1) {
            int total = 5;
            int light = Utils.random.nextInt(total);
            Vec3 location = this.position().add(0, vfxHeight, 0);
            MagicManager.spawnParticles(level, ParticleHelper.FOG_THUNDER_LIGHT, location.x, location.y, location.z, light, 1, 1, 1, 1, true);
            MagicManager.spawnParticles(level, ParticleHelper.FOG_THUNDER_DARK, location.x, location.y, location.z, total - light, 1, 1, 1, 1, true);
            MagicManager.spawnParticles(level, new ShockwaveParticleOptions(SchoolRegistry.LIGHTNING.get().getTargetingColor(), chargeTime * -1.5f * .05f, true), getX(), getY(), getZ(), 1, 0, 0, 0, 0, true);
        }
        if (tickCount == chargeTime) {
            checkHits();
            MagicManager.spawnParticles(level, ParticleHelper.ELECTRIC_SPARKS, getX(), getY(), getZ(), 25, .2f, .2f, .2f, .25, true);
            MagicManager.spawnParticles(level, ParticleHelper.FIERY_SPARKS, getX(), getY(), getZ(), 5, .2f, .2f, .2f, .125, true);
            Vec3 bottom = this.position();
            Vec3 top = bottom.add(0, vfxHeight, 0);
            Vec3 middle = bottom.add(Utils.getRandomScaled(2), Utils.random.nextIntBetweenInclusive(3, vfxHeight - 3), Utils.getRandomScaled(2));
            MagicManager.spawnParticles(level, new ZapParticleOption(top), middle.x, middle.y, middle.z, 1, 0, 0, 0, 0, true);
            MagicManager.spawnParticles(level, new ZapParticleOption(middle), getX(), getY(), getZ(), 1, 0, 0, 0, 0, true);
            if (Utils.random.nextFloat() < .3f) {
                Vec3 split = middle.add(Utils.getRandomScaled(2), -Math.abs(Utils.getRandomScaled(2)), Utils.getRandomScaled(2));
                MagicManager.spawnParticles(level, new ZapParticleOption(middle), split.x, split.y, split.z, 1, 0, 0, 0, 0, true);
            }
            playSound(SoundRegistry.SMALL_LIGHTNING_STRIKE.get(), 2f, .8f + random.nextFloat() * .5f);
        }
        if (this.tickCount > chargeTime) {
            discard();
        }
    }

@Override
    public void applyEffect(LivingEntity target) {
        DamageSources.applyDamage(target, getDamage(), SpellRegistry.THUNDERSTORM_SPELL.get().getDamageSource(this, getOwner()));
    }

protected void checkHits() {
        if (level.isClientSide)
            return;
        List<LivingEntity> targets = this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(this.getInflation().x, this.getInflation().y, this.getInflation().z));
        boolean hit = false;
        var radiusSqr = getRadius();
        radiusSqr *= radiusSqr;
        for (LivingEntity target : targets) {
            if (canHitEntity(target) && (!isCircular() || target.distanceToSqr(this) < radiusSqr)) {
                if (canHitTargetForGroundContext(target)) {
                    applyEffect(target);
                    hit = true;
                }
            }
        }
        if (hit) {
            this.setRadius(getRadius() + radiusOnUse);
            this.duration += durationOnUse;
            onPostHit();
        }
    }

@Override
    protected boolean canHitEntity(Entity pTarget) {
        return (getOwner() == null || (pTarget != getOwner() && !getOwner().isAlliedTo(pTarget))) && super.canHitEntity(pTarget);
    }

protected boolean canHitTargetForGroundContext(LivingEntity target) {
        return target.onGround() || target.getY() - getY() < .5;
    }

@Override
    public void onRecastFinished(ServerPlayer entity, RecastInstance recastInstance, RecastResult recastResult, ICastDataSerializable castDataSerializable) {
        super.onRecastFinished(entity, recastInstance, recastResult, castDataSerializable);
        var serverlevel = entity.serverLevel();
        if (castDataSerializable instanceof MultiTargetEntityCastData targetData && !targetData.getTargets().isEmpty()) {
            Entity orb = serverlevel.getEntity(targetData.getTargets().getFirst());
            if (orb == null) {
                return;
            }
            if (!recastResult.isFailure()) {

                Vec3 dest = TeleportSpell.solveTeleportDestination(serverlevel, entity, orb.blockPosition(), orb.position());
                Vec3 travel = dest.subtract(entity.position());
                if (travel.lengthSqr() < 32 * 32) {
                    zapEntitiesBetween(entity, recastInstance.getSpellLevel(), dest);
                    for (int i = 0; i < 7; i++) {
                        Vec3 random1 = Utils.getRandomVec3(0.5f).multiply(entity.getBbWidth(), entity.getBbHeight(), entity.getBbWidth());
                        Vec3 random2 = Utils.getRandomVec3(0.8f).multiply(entity.getBbWidth(), entity.getBbHeight(), entity.getBbWidth());
                        float yOffset = i / 7f * entity.getBbHeight();
                        Vec3 midpoint = entity.position().add(travel.scale(0.5f)).add(random2);
                        serverlevel.sendParticles(new ZapParticleOption(random1.add(entity.getX(), entity.getY() + yOffset, entity.getZ())), midpoint.x, midpoint.y, midpoint.z, 1, 0, 0, 0, 0);
                        serverlevel.sendParticles(new ZapParticleOption(random1.scale(-1f).add(dest.x, dest.y + yOffset, dest.z)), midpoint.x, midpoint.y, midpoint.z, 1, 0, 0, 0, 0);
                    }
                }

                if (entity.isPassenger()) {
                    entity.stopRiding();
                }
                Utils.handleSpellTeleport(this, entity, dest);
                entity.resetFallDistance();

            }
            orb.discard();
        }
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        if (!playerMagicData.getPlayerRecasts().hasRecastForSpell(this)) {
            /*
            Create and throw orb
             */
            ThunderstepProjectile orb = new ThunderstepProjectile(level, entity);
            orb.shoot(entity.getLookAngle());
            orb.moveTo(entity.getEyePosition());
            level.addFreshEntity(orb);
            var recast = new RecastInstance(getSpellId(), spellLevel, 2, 100, castSource, new MultiTargetEntityCastData(orb));
            playerMagicData.getPlayerRecasts().addRecast(recast, playerMagicData);
        }
        /*
        Normally, there would be an else, but we handle the teleportation logic in the onRecastFinish. recasting again just finishes it faster
         */
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

private void zapEntitiesBetween(LivingEntity caster, int spellLevel, Vec3 blockEnd) {
        Vec3 start = caster.getEyePosition();
        Vec3 end = blockEnd.add(0, caster.getEyeHeight(), 0);
        AABB range = caster.getBoundingBox().expandTowards(end.subtract(start));
        List<? extends Entity> entities = caster.level.getEntities(caster, range);
        for (Entity target : entities) {
            Vec3 height = new Vec3(0, caster.getEyeHeight(), 0);
            //Raycast from eyes and from feet. Rectangular zone of zapping.
            if (Utils.checkEntityIntersecting(target, start, end, 1f).getType() != HitResult.Type.MISS
                    || Utils.checkEntityIntersecting(target, start.subtract(height), end.subtract(height), 1f).getType() != HitResult.Type.MISS) {
                DamageSources.applyDamage(target, getDamage(spellLevel, caster), this.getDamageSource(caster));
            }
        }
    }

@Override
    public void tick() {
        if (!inGround) {
            super.tick();
        } else {
            deltaMovementOld = getDeltaMovement();
            if (tickCount > EXPIRE_TIME) {
                discard();
                return;
            }
            if (shouldFall()) {
                inGround = false;
                this.setDeltaMovement(getDeltaMovement().normalize().scale(0.05f));
            }
        }
    }

@Override
    protected void onHitBlock(BlockHitResult pResult) {
        super.onHitBlock(pResult);
        Vec3 vec3 = pResult.getLocation().subtract(this.getX(), this.getY(), this.getZ());
        this.setDeltaMovement(vec3);
        Vec3 vec31 = vec3.normalize().scale(0.05F);
        this.setPosRaw(this.getX() - vec31.x, this.getY() - vec31.y, this.getZ() - vec31.z);
        this.inGround = true;
    }

@Override
    protected boolean canHitEntity(@NotNull Entity pTarget) {
        return false;
    }

private boolean shouldFall() {
        return this.inGround && this.level.noCollision((new AABB(this.position(), this.position())).inflate(0.06D));
    }

public void tick(int actualTicks) {
        if (serverPlayer != null && serverPlayer.level.getGameTime() % actualTicks == 0) {
            recastLookup.values()
                    .stream()
                    .filter(r -> {
                        r.remainingTicks -= actualTicks;
                        return r.remainingTicks <= 0;
                    })
                    .toList()
                    .forEach(recastInstance -> removeRecast(recastInstance, RecastResult.TIMEOUT));
        }
    }

public void decrementRecastCount(String spellId) {
        //IronsSpellbooks.LOGGER.debug("PlayerRecasts: {} {}", serverPlayer, spellId);
        var recastInstance = recastLookup.get(spellId);

        if (isRecastActive(recastInstance)) {
            recastInstance.remainingRecasts--;

            if (recastInstance.remainingRecasts > 0) {
                recastInstance.remainingTicks = recastInstance.ticksToLive;
                syncToPlayer(recastInstance);
            } else {
                removeRecast(recastInstance, RecastResult.USED_ALL_RECASTS);
            }
        } else if (recastInstance != null) {
            removeRecast(recastInstance, RecastResult.TIMEOUT);
        }
    }

private void triggerRecastComplete(RecastInstance recastInstance, RecastResult recastResult) {
        SpellRegistry.getSpell(recastInstance.getSpellId()).onRecastFinished(serverPlayer, recastInstance, recastResult, recastInstance.castData);
    }

private void removeRecast(RecastInstance recastInstance, RecastResult recastResult, boolean doSync) {
        recastLookup.remove(recastInstance.spellId);
        if (doSync) {
            syncRemoveToPlayer(recastInstance.spellId);
        }
        triggerRecastComplete(recastInstance, recastResult);
    }

public static Vec3 solveTeleportDestination(Level level, LivingEntity entity, BlockPos blockPos, Vec3 vec3) {
        BlockPos pos = blockPos;
        Vec3 bbOffset = entity.getForward().normalize().multiply(entity.getBbWidth() / 3, 0, entity.getBbHeight() / 3);
        Vec3 bbImpact = vec3.subtract(bbOffset);

        double ledgeY = level.clip(new ClipContext(Vec3.atBottomCenterOf(pos).add(0, 3, 0), Vec3.atBottomCenterOf(pos), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, CollisionContext.empty())).getLocation().y;
        boolean isAir = level.getBlockState(new BlockPos(new Vec3i(pos.getX(), (int) ledgeY, pos.getZ())).above()).isAir();
        boolean los = level.clip(new ClipContext(bbImpact, bbImpact.add(0, ledgeY - pos.getY(), 0), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, entity)).getType() == HitResult.Type.MISS;

        if (isAir && los && Math.abs(ledgeY - pos.getY()) <= 3) {
            return new Vec3(pos.getX() + .5, ledgeY + 0.001, pos.getZ() + .5);
        }
        return level.clip(new ClipContext(bbImpact, bbImpact.add(0, -entity.getBbHeight(), 0), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, entity)).getLocation().add(0, 0.001, 0);
    }

public static boolean handleSpellTeleport(AbstractSpell spell, Entity entity, Vec3 destination) {
        var event = new SpellTeleportEvent(spell, entity, destination.x, destination.y, destination.z);
        NeoForge.EVENT_BUS.post(event);
        boolean canceled = event.isCanceled();
        if (!canceled) {
            entity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
        }
        return canceled;
    }

public boolean isFailure() {
        return this == DEATH || this == COUNTERSPELL;
    }
